-- 露营地营位预约与物资租赁管理系统 数据库初始化脚本
-- 生成时间 2026-11-01 14:34:04，库名 new_043，字符集 utf8mb4
-- 含建库、33 张表、索引与覆盖全流程的种子数据；可重复执行（先 DROP 再建）
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

DROP DATABASE IF EXISTS `new_043`;
CREATE DATABASE `new_043` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
USE `new_043`;

DROP TABLE IF EXISTS `sys_user`;
CREATE TABLE `sys_user` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键',
  `username` VARCHAR(50) NOT NULL UNIQUE COMMENT '登录账号',
  `password` VARCHAR(100) NOT NULL COMMENT 'BCrypt 密码，不外泄',
  `real_name` VARCHAR(50) COMMENT '姓名',
  `phone` VARCHAR(30) COMMENT '联系电话',
  `email` VARCHAR(80) COMMENT '邮箱',
  `avatar` VARCHAR(200) COMMENT '头像相对路径',
  `role_code` VARCHAR(30) COMMENT '角色编码：tourist/front/warehouse/manager/admin',
  `org_id` BIGINT COMMENT '所属组织ID',
  `org_name` VARCHAR(80) COMMENT '组织名称冗余',
  `post` VARCHAR(50) COMMENT '岗位，如前台主管、仓库管理员',
  `data_scope` VARCHAR(10) COMMENT '数据范围：ALL/ORG/SELF',
  `status` TINYINT DEFAULT 1 COMMENT '状态：1启用 0停用',
  `fail_count` INT DEFAULT 0 COMMENT '连续登录失败次数',
  `lock_until` DATETIME COMMENT '锁定截止时间',
  `last_login_time` DATETIME COMMENT '最近登录时间',
  `create_time` DATETIME COMMENT '创建时间',
  `update_time` DATETIME COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_sys_user_org_id` (`org_id`),
  KEY `idx_sys_user_status` (`status`),
  KEY `idx_sys_user_create_time` (`create_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='系统用户';

DROP TABLE IF EXISTS `sys_org`;
CREATE TABLE `sys_org` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键',
  `org_name` VARCHAR(80) COMMENT '组织名称',
  `org_code` VARCHAR(30) COMMENT '组织编码',
  `parent_id` BIGINT COMMENT '上级组织',
  `org_type` VARCHAR(20) COMMENT '类型：CAMP/DEPT',
  `leader` VARCHAR(50) COMMENT '负责人',
  `phone` VARCHAR(30) COMMENT '联系电话',
  `sort_no` INT DEFAULT 0 COMMENT '排序',
  `status` TINYINT DEFAULT 1 COMMENT '状态',
  `create_time` DATETIME COMMENT '创建时间',
  `update_time` DATETIME COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_sys_org_parent_id` (`parent_id`),
  KEY `idx_sys_org_status` (`status`),
  KEY `idx_sys_org_create_time` (`create_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='组织/营区部门';

DROP TABLE IF EXISTS `sys_role`;
CREATE TABLE `sys_role` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键',
  `role_code` VARCHAR(30) COMMENT '角色编码',
  `role_name` VARCHAR(50) COMMENT '角色名称',
  `description` VARCHAR(200) COMMENT '说明',
  `status` TINYINT DEFAULT 1 COMMENT '状态',
  `create_time` DATETIME COMMENT '创建时间',
  `update_time` DATETIME COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_sys_role_status` (`status`),
  KEY `idx_sys_role_create_time` (`create_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='角色';

DROP TABLE IF EXISTS `sys_menu`;
CREATE TABLE `sys_menu` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键',
  `menu_name` VARCHAR(50) COMMENT '菜单名称',
  `path` VARCHAR(120) COMMENT '前端路由',
  `icon` VARCHAR(50) COMMENT '图标名',
  `parent_id` BIGINT COMMENT '上级菜单',
  `menu_type` VARCHAR(10) COMMENT '类型：DIR/MENU/BUTTON',
  `visible` TINYINT DEFAULT 1 COMMENT '是否可见',
  `sort_no` INT DEFAULT 0 COMMENT '排序',
  `create_time` DATETIME COMMENT '创建时间',
  `update_time` DATETIME COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_sys_menu_parent_id` (`parent_id`),
  KEY `idx_sys_menu_create_time` (`create_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='菜单';

DROP TABLE IF EXISTS `sys_role_menu`;
CREATE TABLE `sys_role_menu` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键',
  `role_id` BIGINT COMMENT '角色ID',
  `menu_id` BIGINT COMMENT '菜单ID',
  `create_time` DATETIME COMMENT '创建时间',
  `update_time` DATETIME COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_sys_role_menu_role_id` (`role_id`),
  KEY `idx_sys_role_menu_menu_id` (`menu_id`),
  KEY `idx_sys_role_menu_create_time` (`create_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='角色菜单';

DROP TABLE IF EXISTS `sys_dict`;
CREATE TABLE `sys_dict` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键',
  `dict_type` VARCHAR(50) COMMENT '字典类型',
  `dict_label` VARCHAR(50) COMMENT '显示名',
  `dict_value` VARCHAR(50) COMMENT '字典值',
  `sort_no` INT DEFAULT 0 COMMENT '排序',
  `status` TINYINT DEFAULT 1 COMMENT '状态',
  `remark` VARCHAR(200) COMMENT '备注',
  `create_time` DATETIME COMMENT '创建时间',
  `update_time` DATETIME COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_sys_dict_status` (`status`),
  KEY `idx_sys_dict_create_time` (`create_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='数据字典';

DROP TABLE IF EXISTS `sys_message`;
CREATE TABLE `sys_message` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键',
  `title` VARCHAR(120) COMMENT '标题',
  `content` VARCHAR(500) COMMENT '内容',
  `msg_type` VARCHAR(20) COMMENT '类型：TODO/TIMEOUT/BACK/DONE/SYS',
  `biz_no` VARCHAR(50) COMMENT '业务编号',
  `link_url` VARCHAR(200) COMMENT '详情跳转地址',
  `user_id` BIGINT COMMENT '接收人',
  `is_read` TINYINT DEFAULT 0 COMMENT '是否已读',
  `create_time` DATETIME COMMENT '创建时间',
  `update_time` DATETIME COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_sys_message_user_id` (`user_id`),
  KEY `idx_sys_message_create_time` (`create_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='站内消息';

DROP TABLE IF EXISTS `sys_log`;
CREATE TABLE `sys_log` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键',
  `user_id` BIGINT COMMENT '操作人ID',
  `user_name` VARCHAR(50) COMMENT '操作人',
  `action` VARCHAR(80) COMMENT '动作',
  `method` VARCHAR(80) COMMENT '方法',
  `params` VARCHAR(500) COMMENT '参数摘要',
  `cost_ms` BIGINT COMMENT '耗时毫秒',
  `create_time` DATETIME COMMENT '创建时间',
  `update_time` DATETIME COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_sys_log_user_id` (`user_id`),
  KEY `idx_sys_log_create_time` (`create_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='操作日志';

DROP TABLE IF EXISTS `sys_file`;
CREATE TABLE `sys_file` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键',
  `file_name` VARCHAR(200) COMMENT '原始文件名',
  `file_path` VARCHAR(200) COMMENT '相对路径',
  `file_size` BIGINT COMMENT '字节数',
  `file_type` VARCHAR(20) COMMENT '扩展名',
  `bill_type` VARCHAR(30) COMMENT '所属单据类型',
  `bill_id` BIGINT COMMENT '所属单据ID',
  `uploader_id` BIGINT COMMENT '上传人',
  `create_time` DATETIME COMMENT '创建时间',
  `update_time` DATETIME COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_sys_file_bill_id` (`bill_id`),
  KEY `idx_sys_file_uploader_id` (`uploader_id`),
  KEY `idx_sys_file_create_time` (`create_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='附件元数据';

DROP TABLE IF EXISTS `camp_area`;
CREATE TABLE `camp_area` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键',
  `area_code` VARCHAR(30) COMMENT '营区编码',
  `area_name` VARCHAR(60) COMMENT '营区名称',
  `terrain` VARCHAR(30) COMMENT '地形：草坪/林地/湖畔/山脊',
  `site_count` INT DEFAULT 0 COMMENT '营位数量',
  `description` VARCHAR(500) COMMENT '营区说明',
  `cover_image` VARCHAR(200) COMMENT '营区图片',
  `map_image` VARCHAR(200) COMMENT '区域地图',
  `status` VARCHAR(20) COMMENT '状态',
  `create_time` DATETIME COMMENT '创建时间',
  `update_time` DATETIME COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_camp_area_area_code` (`area_code`),
  KEY `idx_camp_area_status` (`status`),
  KEY `idx_camp_area_create_time` (`create_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='营区';

DROP TABLE IF EXISTS `site_type`;
CREATE TABLE `site_type` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键',
  `type_code` VARCHAR(30) COMMENT '类型编码',
  `type_name` VARCHAR(50) COMMENT '类型名称',
  `base_price` DECIMAL(10,2) COMMENT '基础价格（元/晚）',
  `std_capacity` INT COMMENT '标准容量',
  `max_capacity` INT COMMENT '最大容量',
  `description` VARCHAR(300) COMMENT '说明',
  `icon` VARCHAR(50) COMMENT '图标',
  `color` VARCHAR(20) COMMENT '标识色',
  `sort_no` INT DEFAULT 0 COMMENT '排序',
  `status` VARCHAR(20) COMMENT '状态',
  `create_time` DATETIME COMMENT '创建时间',
  `update_time` DATETIME COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_site_type_type_code` (`type_code`),
  KEY `idx_site_type_status` (`status`),
  KEY `idx_site_type_create_time` (`create_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='营位类型';

DROP TABLE IF EXISTS `camp_site`;
CREATE TABLE `camp_site` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键',
  `site_no` VARCHAR(50) COMMENT '营位编号（业务唯一）',
  `site_name` VARCHAR(60) COMMENT '营位名称',
  `area_id` BIGINT COMMENT '所属营区',
  `type_id` BIGINT COMMENT '营位类型',
  `std_capacity` INT COMMENT '标准容量',
  `max_capacity` INT COMMENT '最大容量',
  `area_size` INT COMMENT '面积（平方米）',
  `base_price` DECIMAL(10,2) COMMENT '基础价格（元/晚）',
  `facilities` VARCHAR(300) COMMENT '配套设施，逗号分隔',
  `power_supply` TINYINT DEFAULT 0 COMMENT '是否可用电：1是 0否',
  `environment` VARCHAR(300) COMMENT '相邻环境说明',
  `cover_image` VARCHAR(200) COMMENT '列表图',
  `detail_image` VARCHAR(200) COMMENT '详情图',
  `status` VARCHAR(20) COMMENT '营位状态：FREE/RESERVED/OCCUPIED/CLEANING/REPAIR/OFF',
  `open_date` DATE COMMENT '开放日期',
  `device_note` VARCHAR(300) COMMENT '维护/停用说明',
  `version` INT DEFAULT 0 COMMENT '乐观锁版本',
  `create_by` BIGINT COMMENT '创建人',
  `create_time` DATETIME COMMENT '创建时间',
  `update_time` DATETIME COMMENT '更新时间',
  `deleted` TINYINT DEFAULT 0 COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_camp_site_site_no` (`site_no`),
  KEY `idx_camp_site_area_id` (`area_id`),
  KEY `idx_camp_site_type_id` (`type_id`),
  KEY `idx_camp_site_status` (`status`),
  KEY `idx_camp_site_create_time` (`create_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='营位主档';

DROP TABLE IF EXISTS `site_price`;
CREATE TABLE `site_price` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键',
  `site_id` BIGINT COMMENT '营位ID',
  `rule_type` VARCHAR(20) COMMENT '类型：HOLIDAY/WEEKEND/PEAK',
  `start_date` DATE COMMENT '开始日期',
  `end_date` DATE COMMENT '结束日期',
  `price` DECIMAL(10,2) COMMENT '价格',
  `remark` VARCHAR(200) COMMENT '说明',
  `create_time` DATETIME COMMENT '创建时间',
  `update_time` DATETIME COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_site_price_site_id` (`site_id`),
  KEY `idx_site_price_create_time` (`create_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='特殊日期价格';

DROP TABLE IF EXISTS `booking`;
CREATE TABLE `booking` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键',
  `booking_no` VARCHAR(40) COMMENT '预约编号',
  `user_id` BIGINT COMMENT '预订人',
  `customer_name` VARCHAR(50) COMMENT '预订人姓名',
  `customer_phone` VARCHAR(30) COMMENT '联系电话',
  `site_id` BIGINT COMMENT '营位ID',
  `site_no` VARCHAR(50) COMMENT '营位编号冗余',
  `check_in_date` DATE COMMENT '入住日期',
  `check_out_date` DATE COMMENT '退营日期',
  `nights` INT COMMENT '晚数',
  `guest_count` INT COMMENT '入住人数',
  `special_need` VARCHAR(300) COMMENT '儿童/老人/特殊人群说明',
  `source` VARCHAR(20) COMMENT '来源：WEB/PHONE/WALKIN',
  `site_fee` DECIMAL(10,2) COMMENT '营位费',
  `goods_fee` DECIMAL(10,2) COMMENT '物资租金',
  `deposit` DECIMAL(10,2) COMMENT '押金',
  `total_fee` DECIMAL(10,2) COMMENT '合计金额',
  `status` VARCHAR(20) COMMENT '状态：DRAFT/SUBMITTED/CONFIRMED/RESERVED/OCCUPIED/CHECKED/COMPLETED/CANCELLED/REJECTED/NOSHOW',
  `responsible_id` BIGINT COMMENT '当前责任人',
  `cancel_reason` VARCHAR(300) COMMENT '取消原因',
  `remark` VARCHAR(300) COMMENT '备注',
  `version` INT DEFAULT 0 COMMENT '乐观锁版本',
  `create_time` DATETIME COMMENT '创建时间',
  `update_time` DATETIME COMMENT '更新时间',
  `deleted` TINYINT DEFAULT 0 COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_booking_booking_no` (`booking_no`),
  KEY `idx_booking_user_id` (`user_id`),
  KEY `idx_booking_site_id` (`site_id`),
  KEY `idx_booking_site_no` (`site_no`),
  KEY `idx_booking_check_in_date` (`check_in_date`),
  KEY `idx_booking_status` (`status`),
  KEY `idx_booking_responsible_id` (`responsible_id`),
  KEY `idx_booking_create_time` (`create_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='营位预约与物资租赁主单';

DROP TABLE IF EXISTS `booking_change`;
CREATE TABLE `booking_change` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键',
  `booking_id` BIGINT COMMENT '预约ID',
  `change_type` VARCHAR(20) COMMENT '类型：CONFIRM/REJECT/RESCHEDULE/CANCEL/ARRIVE/NOSHOW',
  `old_value` VARCHAR(200) COMMENT '变更前',
  `new_value` VARCHAR(200) COMMENT '变更后',
  `reason` VARCHAR(300) COMMENT '原因（不少于5字）',
  `operator_id` BIGINT COMMENT '操作人',
  `operator_name` VARCHAR(50) COMMENT '操作人姓名',
  `create_time` DATETIME COMMENT '创建时间',
  `update_time` DATETIME COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_booking_change_booking_id` (`booking_id`),
  KEY `idx_booking_change_operator_id` (`operator_id`),
  KEY `idx_booking_change_create_time` (`create_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='预约变更记录';

DROP TABLE IF EXISTS `guest_member`;
CREATE TABLE `guest_member` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键',
  `booking_id` BIGINT COMMENT '预约ID',
  `guest_name` VARCHAR(50) COMMENT '姓名',
  `phone` VARCHAR(30) COMMENT '联系方式',
  `age_group` VARCHAR(20) COMMENT '年龄段：ADULT/CHILD/ELDER',
  `id_card` VARCHAR(20) COMMENT '证件号后四位',
  `emergency_contact` VARCHAR(50) COMMENT '紧急联系人',
  `emergency_phone` VARCHAR(30) COMMENT '紧急联系电话',
  `safety_confirmed` TINYINT DEFAULT 0 COMMENT '安全提示是否确认',
  `remark` VARCHAR(200) COMMENT '备注',
  `create_time` DATETIME COMMENT '创建时间',
  `update_time` DATETIME COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_guest_member_booking_id` (`booking_id`),
  KEY `idx_guest_member_create_time` (`create_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='同行人';

DROP TABLE IF EXISTS `booking_vehicle`;
CREATE TABLE `booking_vehicle` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键',
  `booking_id` BIGINT COMMENT '预约ID',
  `plate_no` VARCHAR(20) COMMENT '车牌号',
  `vehicle_type` VARCHAR(30) COMMENT '车型',
  `seat_count` INT COMMENT '核载人数',
  `arrive_time` DATETIME COMMENT '预计到达时间',
  `remark` VARCHAR(200) COMMENT '备注',
  `create_time` DATETIME COMMENT '创建时间',
  `update_time` DATETIME COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_booking_vehicle_booking_id` (`booking_id`),
  KEY `idx_booking_vehicle_create_time` (`create_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='入营车辆';

DROP TABLE IF EXISTS `goods_category`;
CREATE TABLE `goods_category` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键',
  `category_name` VARCHAR(50) COMMENT '分类名称',
  `icon` VARCHAR(50) COMMENT '图标',
  `sort_no` INT DEFAULT 0 COMMENT '排序',
  `status` VARCHAR(20) COMMENT '状态',
  `create_time` DATETIME COMMENT '创建时间',
  `update_time` DATETIME COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_goods_category_status` (`status`),
  KEY `idx_goods_category_create_time` (`create_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='物资分类';

DROP TABLE IF EXISTS `goods`;
CREATE TABLE `goods` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键',
  `goods_no` VARCHAR(40) COMMENT '物资编号',
  `goods_name` VARCHAR(80) COMMENT '物资名称',
  `category_id` BIGINT COMMENT '分类',
  `spec` VARCHAR(100) COMMENT '规格',
  `total_stock` INT DEFAULT 0 COMMENT '总库存',
  `deposit` DECIMAL(10,2) COMMENT '押金',
  `rent_price` DECIMAL(10,2) COMMENT '租金',
  `rent_unit` VARCHAR(10) COMMENT '计价单位：晚/天/套',
  `turnover_hours` INT DEFAULT 2 COMMENT '周转缓冲小时（清洁检查）',
  `image` VARCHAR(200) COMMENT '图片',
  `status` VARCHAR(20) COMMENT '状态',
  `remark` VARCHAR(200) COMMENT '备注',
  `create_time` DATETIME COMMENT '创建时间',
  `update_time` DATETIME COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_goods_goods_no` (`goods_no`),
  KEY `idx_goods_category_id` (`category_id`),
  KEY `idx_goods_status` (`status`),
  KEY `idx_goods_create_time` (`create_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='租赁物资';

DROP TABLE IF EXISTS `goods_stock`;
CREATE TABLE `goods_stock` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键',
  `goods_id` BIGINT COMMENT '物资ID',
  `stock_date` DATE COMMENT '库存日期',
  `total_qty` INT DEFAULT 0 COMMENT '库存总量',
  `occupied_qty` INT DEFAULT 0 COMMENT '已预占',
  `available_qty` INT DEFAULT 0 COMMENT '可用',
  `damaged_qty` INT DEFAULT 0 COMMENT '损坏待修',
  `update_time` DATETIME COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_goods_stock_goods_id` (`goods_id`),
  KEY `idx_goods_stock_stock_date` (`stock_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='物资日库存';

DROP TABLE IF EXISTS `rent_item`;
CREATE TABLE `rent_item` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键',
  `booking_id` BIGINT COMMENT '预约ID',
  `goods_id` BIGINT COMMENT '物资ID',
  `goods_name` VARCHAR(80) COMMENT '物资名称冗余',
  `qty` INT COMMENT '数量',
  `rent_days` INT COMMENT '租用时长',
  `unit_price` DECIMAL(10,2) COMMENT '单价',
  `deposit` DECIMAL(10,2) COMMENT '押金小计',
  `amount` DECIMAL(10,2) COMMENT '租金小计',
  `status` VARCHAR(20) COMMENT '状态：PENDING/PICKED/RETURNED/DAMAGED/LOST',
  `create_time` DATETIME COMMENT '创建时间',
  `update_time` DATETIME COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_rent_item_booking_id` (`booking_id`),
  KEY `idx_rent_item_goods_id` (`goods_id`),
  KEY `idx_rent_item_status` (`status`),
  KEY `idx_rent_item_create_time` (`create_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='租赁明细';

DROP TABLE IF EXISTS `rent_handover`;
CREATE TABLE `rent_handover` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键',
  `rent_item_id` BIGINT COMMENT '租赁明细ID',
  `booking_id` BIGINT COMMENT '预约ID',
  `goods_id` BIGINT COMMENT '物资ID',
  `handover_type` VARCHAR(10) COMMENT '类型：OUT/IN',
  `qty` INT COMMENT '数量',
  `serial_no` VARCHAR(80) COMMENT '序列号',
  `item_status` VARCHAR(20) COMMENT '物品状态：GOOD/DIRTY/DAMAGED/LOST',
  `photo` VARCHAR(200) COMMENT '交接照片',
  `operator_id` BIGINT COMMENT '经办人',
  `operator_name` VARCHAR(50) COMMENT '经办人姓名',
  `handover_time` DATETIME COMMENT '交接时间',
  `remark` VARCHAR(200) COMMENT '备注',
  `create_time` DATETIME COMMENT '创建时间',
  `update_time` DATETIME COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_rent_handover_rent_item_id` (`rent_item_id`),
  KEY `idx_rent_handover_booking_id` (`booking_id`),
  KEY `idx_rent_handover_goods_id` (`goods_id`),
  KEY `idx_rent_handover_operator_id` (`operator_id`),
  KEY `idx_rent_handover_create_time` (`create_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='物资发放归还';

DROP TABLE IF EXISTS `checkin_record`;
CREATE TABLE `checkin_record` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键',
  `booking_id` BIGINT COMMENT '预约ID',
  `handover_no` VARCHAR(40) COMMENT '交接单号',
  `site_id` BIGINT COMMENT '营位ID',
  `actual_guest_count` INT COMMENT '实际人数',
  `deposit` DECIMAL(10,2) COMMENT '收取押金',
  `safety_confirmed` TINYINT DEFAULT 0 COMMENT '安全须知确认',
  `site_photo` VARCHAR(200) COMMENT '营位交接照片',
  `goods_photo` VARCHAR(200) COMMENT '物资交接照片',
  `operator_id` BIGINT COMMENT '经办人',
  `operator_name` VARCHAR(50) COMMENT '经办人姓名',
  `checkin_time` DATETIME COMMENT '入住时间',
  `status` VARCHAR(20) COMMENT '状态：DONE/VOID',
  `remark` VARCHAR(300) COMMENT '备注',
  `create_time` DATETIME COMMENT '创建时间',
  `update_time` DATETIME COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_checkin_record_booking_id` (`booking_id`),
  UNIQUE KEY `uk_checkin_record_handover_no` (`handover_no`),
  KEY `idx_checkin_record_site_id` (`site_id`),
  KEY `idx_checkin_record_operator_id` (`operator_id`),
  KEY `idx_checkin_record_status` (`status`),
  KEY `idx_checkin_record_create_time` (`create_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='入住交接';

DROP TABLE IF EXISTS `patrol_task`;
CREATE TABLE `patrol_task` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键',
  `task_no` VARCHAR(40) COMMENT '任务编号',
  `area_id` BIGINT COMMENT '营区ID',
  `task_type` VARCHAR(20) COMMENT '类型：FIRE/POWER/SANITARY/ROAD/FACILITY',
  `plan_date` DATE COMMENT '计划日期',
  `inspector_id` BIGINT COMMENT '巡检人',
  `inspector_name` VARCHAR(50) COMMENT '巡检人姓名',
  `status` VARCHAR(20) COMMENT '状态：PENDING/RUNNING/DONE/OVERDUE',
  `result` VARCHAR(20) COMMENT '结果：NORMAL/PROBLEM',
  `problem_level` VARCHAR(10) COMMENT '问题级别：LOW/MID/HIGH',
  `problem_desc` VARCHAR(300) COMMENT '问题描述',
  `image` VARCHAR(200) COMMENT '现场照片',
  `rectify_owner` VARCHAR(50) COMMENT '整改责任人',
  `deadline` DATE COMMENT '整改期限',
  `finish_time` DATETIME COMMENT '完成时间',
  `create_time` DATETIME COMMENT '创建时间',
  `update_time` DATETIME COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_patrol_task_task_no` (`task_no`),
  KEY `idx_patrol_task_area_id` (`area_id`),
  KEY `idx_patrol_task_plan_date` (`plan_date`),
  KEY `idx_patrol_task_inspector_id` (`inspector_id`),
  KEY `idx_patrol_task_status` (`status`),
  KEY `idx_patrol_task_create_time` (`create_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='巡检任务';

DROP TABLE IF EXISTS `hazard`;
CREATE TABLE `hazard` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键',
  `hazard_no` VARCHAR(40) COMMENT '隐患编号',
  `task_id` BIGINT COMMENT '来源巡检任务',
  `area_id` BIGINT COMMENT '营区ID',
  `hazard_type` VARCHAR(30) COMMENT '隐患类型',
  `level` VARCHAR(10) COMMENT '级别：LOW/MID/HIGH',
  `description` VARCHAR(300) COMMENT '描述',
  `image` VARCHAR(200) COMMENT '现场照片',
  `rectify_owner` VARCHAR(50) COMMENT '整改责任人',
  `deadline` DATE COMMENT '整改期限',
  `status` VARCHAR(20) COMMENT '状态：OPEN/RECTIFY/CLOSED',
  `close_time` DATETIME COMMENT '关闭时间',
  `create_time` DATETIME COMMENT '创建时间',
  `update_time` DATETIME COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_hazard_hazard_no` (`hazard_no`),
  KEY `idx_hazard_task_id` (`task_id`),
  KEY `idx_hazard_area_id` (`area_id`),
  KEY `idx_hazard_status` (`status`),
  KEY `idx_hazard_create_time` (`create_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='隐患台账';

DROP TABLE IF EXISTS `camp_event`;
CREATE TABLE `camp_event` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键',
  `event_no` VARCHAR(40) COMMENT '事件编号',
  `event_type` VARCHAR(20) COMMENT '类型：WEATHER/NOISE/DEVICE/OTHER',
  `level` VARCHAR(10) COMMENT '级别',
  `content` VARCHAR(300) COMMENT '事件内容',
  `site_id` BIGINT COMMENT '关联营位',
  `reporter_id` BIGINT COMMENT '上报人',
  `reporter_name` VARCHAR(50) COMMENT '上报人姓名',
  `handle_status` VARCHAR(20) COMMENT '处理状态：OPEN/HANDLING/CLOSED',
  `handle_result` VARCHAR(300) COMMENT '处理结果',
  `handle_time` DATETIME COMMENT '处理时间',
  `create_time` DATETIME COMMENT '创建时间',
  `update_time` DATETIME COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_camp_event_event_no` (`event_no`),
  KEY `idx_camp_event_site_id` (`site_id`),
  KEY `idx_camp_event_reporter_id` (`reporter_id`),
  KEY `idx_camp_event_create_time` (`create_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='运营事件';

DROP TABLE IF EXISTS `checkout_record`;
CREATE TABLE `checkout_record` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键',
  `booking_id` BIGINT COMMENT '预约ID',
  `cleanliness` INT COMMENT '卫生评分 1-5',
  `goods_qty_ok` TINYINT DEFAULT 1 COMMENT '物资数量是否齐全',
  `damage_desc` VARCHAR(300) COMMENT '损坏说明',
  `overdue_hours` DECIMAL(6,1) COMMENT '超时小时数',
  `site_fee` DECIMAL(10,2) COMMENT '营位费',
  `goods_fee` DECIMAL(10,2) COMMENT '物资租金',
  `overtime_fee` DECIMAL(10,2) COMMENT '超时费',
  `damage_fee` DECIMAL(10,2) COMMENT '损坏赔偿',
  `deposit_refund` DECIMAL(10,2) COMMENT '押金退还',
  `discount` DECIMAL(10,2) COMMENT '优惠减免',
  `total_amount` DECIMAL(10,2) COMMENT '应收合计',
  `status` VARCHAR(20) COMMENT '状态：DRAFT/SETTLED',
  `operator_id` BIGINT COMMENT '经办人',
  `operator_name` VARCHAR(50) COMMENT '经办人姓名',
  `check_time` DATETIME COMMENT '验收时间',
  `photo` VARCHAR(200) COMMENT '验收照片',
  `remark` VARCHAR(300) COMMENT '备注',
  `create_time` DATETIME COMMENT '创建时间',
  `update_time` DATETIME COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_checkout_record_booking_id` (`booking_id`),
  KEY `idx_checkout_record_status` (`status`),
  KEY `idx_checkout_record_operator_id` (`operator_id`),
  KEY `idx_checkout_record_create_time` (`create_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='退营验收与结算';

DROP TABLE IF EXISTS `fee_item`;
CREATE TABLE `fee_item` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键',
  `booking_id` BIGINT COMMENT '预约ID',
  `checkout_id` BIGINT COMMENT '结算单ID',
  `fee_type` VARCHAR(20) COMMENT '类型：SITE/GOODS/OVERTIME/DAMAGE/DISCOUNT/DEPOSIT',
  `fee_name` VARCHAR(80) COMMENT '费用名称',
  `amount` DECIMAL(10,2) COMMENT '金额',
  `remark` VARCHAR(200) COMMENT '备注',
  `create_time` DATETIME COMMENT '创建时间',
  `update_time` DATETIME COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_fee_item_booking_id` (`booking_id`),
  KEY `idx_fee_item_checkout_id` (`checkout_id`),
  KEY `idx_fee_item_create_time` (`create_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='费用明细';

DROP TABLE IF EXISTS `payment`;
CREATE TABLE `payment` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键',
  `pay_no` VARCHAR(40) COMMENT '收款单号',
  `booking_id` BIGINT COMMENT '预约ID',
  `checkout_id` BIGINT COMMENT '结算单ID',
  `pay_type` VARCHAR(20) COMMENT '方式：CASH/WECHAT/ALIPAY/CARD',
  `amount` DECIMAL(10,2) COMMENT '金额',
  `pay_time` DATETIME COMMENT '收款时间',
  `operator_id` BIGINT COMMENT '经办人',
  `operator_name` VARCHAR(50) COMMENT '经办人姓名',
  `status` VARCHAR(20) COMMENT '状态：PAID/REFUND',
  `remark` VARCHAR(200) COMMENT '备注',
  `create_time` DATETIME COMMENT '创建时间',
  `update_time` DATETIME COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_payment_pay_no` (`pay_no`),
  KEY `idx_payment_booking_id` (`booking_id`),
  KEY `idx_payment_checkout_id` (`checkout_id`),
  KEY `idx_payment_operator_id` (`operator_id`),
  KEY `idx_payment_status` (`status`),
  KEY `idx_payment_create_time` (`create_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='线下收款记录';

DROP TABLE IF EXISTS `review`;
CREATE TABLE `review` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键',
  `booking_id` BIGINT COMMENT '预约ID',
  `user_id` BIGINT COMMENT '评价人',
  `customer_name` VARCHAR(50) COMMENT '评价人姓名',
  `site_score` INT COMMENT '营位环境分',
  `env_score` INT COMMENT '自然环境分',
  `facility_score` INT COMMENT '设施分',
  `service_score` INT COMMENT '服务分',
  `avg_score` DECIMAL(3,2) COMMENT '平均分',
  `content` VARCHAR(500) COMMENT '评价内容',
  `images` VARCHAR(500) COMMENT '图片，逗号分隔',
  `reply` VARCHAR(500) COMMENT '商家回复',
  `reply_time` DATETIME COMMENT '回复时间',
  `create_time` DATETIME COMMENT '创建时间',
  `update_time` DATETIME COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_review_booking_id` (`booking_id`),
  KEY `idx_review_user_id` (`user_id`),
  KEY `idx_review_create_time` (`create_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='服务评价';

DROP TABLE IF EXISTS `blacklist`;
CREATE TABLE `blacklist` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键',
  `user_id` BIGINT COMMENT '客户ID',
  `customer_name` VARCHAR(50) COMMENT '客户姓名',
  `phone` VARCHAR(30) COMMENT '联系电话',
  `reason_type` VARCHAR(20) COMMENT '类型：DAMAGE/VIOLATION/NOSHOW',
  `reason` VARCHAR(300) COMMENT '原因',
  `status` VARCHAR(20) COMMENT '状态：PENDING/ACTIVE/RELEASED/REJECTED',
  `apply_by` BIGINT COMMENT '申请人',
  `apply_name` VARCHAR(50) COMMENT '申请人姓名',
  `audit_by` BIGINT COMMENT '审批人',
  `audit_name` VARCHAR(50) COMMENT '审批人姓名',
  `audit_time` DATETIME COMMENT '审批时间',
  `audit_note` VARCHAR(300) COMMENT '审批意见',
  `release_time` DATETIME COMMENT '解除时间',
  `create_time` DATETIME COMMENT '创建时间',
  `update_time` DATETIME COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_blacklist_user_id` (`user_id`),
  KEY `idx_blacklist_status` (`status`),
  KEY `idx_blacklist_create_time` (`create_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='黑名单';

DROP TABLE IF EXISTS `avail_rule`;
CREATE TABLE `avail_rule` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键',
  `rule_name` VARCHAR(80) COMMENT '规则名称',
  `version` INT COMMENT '版本号',
  `w_site_time` DECIMAL(5,2) COMMENT '营位时段权重',
  `w_capacity` DECIMAL(5,2) COMMENT '容纳人数权重',
  `w_facility` DECIMAL(5,2) COMMENT '设施需求权重',
  `w_stock` DECIMAL(5,2) COMMENT '物资库存权重',
  `w_turnover` DECIMAL(5,2) COMMENT '物资周转权重',
  `w_maintain` DECIMAL(5,2) COMMENT '维护状态权重',
  `threshold_high` DECIMAL(5,2) COMMENT '推荐阈值',
  `threshold_mid` DECIMAL(5,2) COMMENT '可接受阈值',
  `status` VARCHAR(20) COMMENT '状态：ENABLED/ARCHIVED',
  `effective_time` DATETIME COMMENT '生效时间',
  `create_by` BIGINT COMMENT '创建人',
  `create_name` VARCHAR(50) COMMENT '创建人姓名',
  `create_time` DATETIME COMMENT '创建时间',
  `update_time` DATETIME COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_avail_rule_status` (`status`),
  KEY `idx_avail_rule_create_time` (`create_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='联合可用性规则版本';

DROP TABLE IF EXISTS `avail_score`;
CREATE TABLE `avail_score` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键',
  `booking_id` BIGINT COMMENT '预约ID',
  `site_id` BIGINT COMMENT '营位ID',
  `rule_version` INT COMMENT '规则版本',
  `input_snapshot` TEXT COMMENT '输入快照 JSON',
  `s_site_time` DECIMAL(5,2) COMMENT '营位时段得分',
  `s_capacity` DECIMAL(5,2) COMMENT '容纳人数得分',
  `s_facility` DECIMAL(5,2) COMMENT '设施需求得分',
  `s_stock` DECIMAL(5,2) COMMENT '物资库存得分',
  `s_turnover` DECIMAL(5,2) COMMENT '物资周转得分',
  `s_maintain` DECIMAL(5,2) COMMENT '维护状态得分',
  `total_score` DECIMAL(5,2) COMMENT '总分',
  `level` VARCHAR(10) COMMENT '等级：HIGH/MID/LOW',
  `main_factor` VARCHAR(200) COMMENT '主要影响因素',
  `unmet` VARCHAR(500) COMMENT '未满足条件',
  `improve_tip` VARCHAR(500) COMMENT '可改进项',
  `suggest_json` TEXT COMMENT '替代组合建议 JSON',
  `manual_level` VARCHAR(10) COMMENT '人工调整后等级',
  `manual_reason` VARCHAR(300) COMMENT '人工调整原因',
  `manual_by` BIGINT COMMENT '调整人',
  `manual_name` VARCHAR(50) COMMENT '调整人姓名',
  `manual_time` DATETIME COMMENT '调整时间',
  `create_time` DATETIME COMMENT '创建时间',
  `update_time` DATETIME COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_avail_score_booking_id` (`booking_id`),
  KEY `idx_avail_score_site_id` (`site_id`),
  KEY `idx_avail_score_create_time` (`create_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='联合可用性计算留痕';

