-- ---------- 营区、营位类型、营位 ----------
INSERT INTO `camp_area` (`area_code`,`area_name`,`terrain`,`site_count`,`description`,`cover_image`,`map_image`,`status`,`create_time`,`update_time`) VALUES
('A','湖畔草坪区','湖畔',8,'紧邻听雨湖西岸，草坪平整，视野开阔，适合家庭帐篷与野餐。夜间可看星，风较大需加固地钉。','/uploads/seed/area/01.jpg','/uploads/seed/area/01.jpg','OPEN','2026-03-06 14:34:04','2026-11-01 14:34:04'),
('B','林间静语区','林地',6,'百年杉木林下，日照柔和，夏季凉爽。地面有树根，推荐使用加厚睡垫。','/uploads/seed/area/02.jpg','/uploads/seed/area/02.jpg','OPEN','2026-03-06 14:34:04','2026-11-01 14:34:04'),
('C','亲子活动区','草坪',6,'靠近儿童游乐场与公共洗手间，步行 2 分钟可达，适合带小孩的家庭。','/uploads/seed/area/03.jpg','/uploads/seed/area/03.jpg','OPEN','2026-03-06 14:34:04','2026-11-01 14:34:04'),
('D','山脊观景区','山脊',4,'海拔较高的山脊平台，日出与云海视野最佳，进出需经 300 米碎石坡道。','/uploads/seed/area/04.jpg','/uploads/seed/area/04.jpg','OPEN','2026-03-06 14:34:04','2026-11-01 14:34:04');

