SET FOREIGN_KEY_CHECKS = 1;

-- 数据摘要（供核对）
-- 营区4 / 营位类型5 / 营位24 / 物资16 / 预约44 / 租赁明细87
-- 交接88 / 入住25 / 结算21 / 费用79 / 收款18
-- 评价15 / 黑名单4 / 巡检34 / 隐患9 / 事件14
-- 规则版本3 / 评分留痕37 / 消息21 / 日志60
-- 让最近 6 笔已结算单落在本月，保证经营看板「当月收入」有数据
UPDATE checkout_record SET check_time = DATE_ADD(DATE_FORMAT(NOW(),'%Y-%m-01'), INTERVAL (id % 8) HOUR) WHERE status = 'SETTLED' ORDER BY id DESC LIMIT 6;
UPDATE payment SET pay_time = (SELECT c.check_time FROM checkout_record c WHERE c.id = payment.checkout_id) WHERE checkout_id IN (SELECT id FROM (SELECT id FROM checkout_record WHERE status = 'SETTLED' ORDER BY id DESC LIMIT 6) t);
-- 让 1 条待确认预约的入住日期就是今天，看板「今日到店」不为 0
UPDATE booking SET check_in_date = CURDATE(), check_out_date = DATE_ADD(CURDATE(), INTERVAL 2 DAY) WHERE id = (SELECT id FROM (SELECT id FROM booking WHERE status = 'SUBMITTED' ORDER BY id LIMIT 1) t);
